CREATE OR REPLACE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id from public.contract_products cp where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id from public.legal_bundle_versions lb where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    else v_company_id := null;
  end case;
  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(v_company_id,'website',tg_table_name || '.' || lower(tg_op),v_entity_id);
    perform public.gridex_bump_contract_publication_revision(v_company_id,'api',tg_table_name || '.' || lower(tg_op),v_entity_id);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_validate_partner_export_payload(p_export_kind text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_customer_id text;
  v_customer_name text;
  v_customer_email text;
  v_customer_phone text;
  v_personal_number text;
  v_org_number text;
  v_site_id text;
  v_metering_point_id text;
  v_contract_id text;
  v_contract_status text;
begin
  v_customer_id := public.gridex_jsonb_text(p_payload, array['customer','id']);
  v_customer_name := public.gridex_jsonb_text(p_payload, array['customer','full_name']);
  v_customer_email := public.gridex_jsonb_text(p_payload, array['customer','email']);
  v_customer_phone := public.gridex_jsonb_text(p_payload, array['customer','phone']);
  v_personal_number := public.gridex_jsonb_text(p_payload, array['customer','personal_number']);
  v_org_number := public.gridex_jsonb_text(p_payload, array['customer','org_number']);
  v_site_id := public.gridex_jsonb_text(p_payload, array['site','id']);
  v_metering_point_id := public.gridex_jsonb_text(p_payload, array['metering_point','id']);
  v_contract_id := public.gridex_jsonb_text(p_payload, array['contract','id']);
  v_contract_status := public.gridex_jsonb_text(p_payload, array['contract','status']);

  if v_customer_id is null then
    raise exception 'Partner export payload missing customer.id';
  end if;

  if v_customer_name is null then
    raise exception 'Partner export payload missing customer.full_name';
  end if;

  if v_customer_email is null and v_customer_phone is null then
    raise exception 'Partner export payload missing both customer.email and customer.phone';
  end if;

  if v_personal_number is null and v_org_number is null then
    raise exception 'Partner export payload missing both customer.personal_number and customer.org_number';
  end if;

  if p_export_kind in ('billing_underlay', 'meter_values') and v_site_id is null then
    raise exception 'Partner export payload missing site.id';
  end if;

  if p_export_kind in ('billing_underlay', 'meter_values') and v_metering_point_id is null then
    raise exception 'Partner export payload missing metering_point.id';
  end if;

  if p_export_kind in ('billing_underlay', 'meter_values') then
    if v_contract_id is null then
      raise exception 'Partner export payload missing contract.id';
    end if;

    if v_contract_status not in ('signed', 'active', 'terminated') then
      raise exception 'Partner export payload invalid contract.status=%',
        coalesce(v_contract_status, 'null');
    end if;
  end if;
end;
$function$
